SELECT country, DATE_TRUNC('QUARTER', started_at) AS quarter_start, COUNT(CASE WHEN country = 'SG' THEN 1 END) AS sg_count, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes, COUNT(DISTINCT browser) AS distinct_browsers, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, GROUPING(country) AS gid FROM sessions GROUP BY GROUPING SETS ((country, DATE_TRUNC('QUARTER', started_at)), (country), ());
